using System.Text;

namespace Pyrlyn.CommandLine.Docs;

/// <summary>
/// Static completion scripts from a command model. Each one finds the command path in the words
/// typed so far (skipping the value after an option that takes one) and offers that path's next
/// words, or its options when the word starts with <c>-</c>. An option's value and a command's
/// arguments fall back to file names. Byte-stable for a given model.
/// </summary>
public static class CompletionScripts
{
    private const string Generated =
        "Generated by Pyrlyn.CommandLine.Docs from the command model; do not edit.";

    /// <summary>All five scripts: <c>&lt;name&gt;.bash</c>, <c>_&lt;name&gt;</c> (zsh), <c>&lt;name&gt;.fish</c>, <c>&lt;name&gt;.ps1</c> and <c>&lt;name&gt;.lua</c> (clink).</summary>
    /// <param name="model">The model.</param>
    /// <returns>The scripts.</returns>
    public static IReadOnlyList<GeneratedFile> Render(CommandModel model)
    {
        ArgumentNullException.ThrowIfNull(model);
        return
        [
            new($"{model.Name}.bash", Bash(model)),
            new($"_{model.Name}", Zsh(model)),
            new($"{model.Name}.fish", Fish(model)),
            new($"{model.Name}.ps1", PowerShell(model)),
            new($"{model.Name}.lua", Clink(model)),
        ];
    }

    /// <summary>A bash script for <c>complete -F</c>.</summary>
    /// <param name="model">The model.</param>
    /// <returns>The script.</returns>
    public static string Bash(CommandModel model)
    {
        var tree = CommandTree.From(model);
        var fn = "_" + Identifier(tree.Name);
        var sb = new StringBuilder();
        sb.Append($"# bash completion for {tree.Name}\n# {Generated}\n");
        void Table(string suffix, Func<CommandTree.Node, IEnumerable<string>> words) =>
            CaseTable(
                sb,
                $"\n{fn}_{suffix}() {{\n    case $1 in\n",
                tree,
                n =>
                    words(n).ToList() is { Count: > 0 } list
                        ? $"        {Sh(n.Path)}) echo {Sh(string.Join(' ', list))} ;;"
                        : null,
                "    esac\n}\n"
            );
        Table("children", n => n.Children.Select(c => c.Word));
        Table("options", n => n.Options.SelectMany(o => o.Names));
        Table("values", ValueNames);
        sb.Append(BashMain(fn, tree.Name));
        return sb.ToString();
    }

    /// <summary>A zsh completion function file (install it as <c>_&lt;name&gt;</c> on <c>$fpath</c>).</summary>
    /// <param name="model">The model.</param>
    /// <returns>The script.</returns>
    public static string Zsh(CommandModel model)
    {
        var tree = CommandTree.From(model);
        var fn = "_" + Identifier(tree.Name);
        var sb = new StringBuilder();
        sb.Append($"#compdef {tree.Name}\n# zsh completion for {tree.Name}\n# {Generated}\n");
        void Table(string suffix, Func<CommandTree.Node, IEnumerable<string>> items) =>
            CaseTable(
                sb,
                $"\n{fn}_{suffix}() {{\n  case $1 in\n",
                tree,
                n =>
                    items(n).Select(Sh).ToList() is { Count: > 0 } list
                        ? $"    {Sh(n.Path)}) items=({string.Join(' ', list)}) ;;"
                        : null,
                "  esac\n}\n"
            );
        Table("children", n => n.Children.Select(c => Described(c.Word, c.Hint)));
        Table(
            "options",
            n =>
                n.Options.SelectMany(o =>
                    o.Names.Select(name => Described(name, CommandTree.FirstLine(o.Description)))
                )
        );
        Table("values", ValueNames);
        sb.Append(ZshMain(fn, tree.Name));
        return sb.ToString();
    }

    /// <summary>A fish completion file (install it as <c>&lt;name&gt;.fish</c> in <c>completions/</c>).</summary>
    /// <param name="model">The model.</param>
    /// <returns>The script.</returns>
    public static string Fish(CommandModel model)
    {
        var tree = CommandTree.From(model);
        var fn = "__" + Identifier(tree.Name);
        var paths = tree.Nodes.Where(n => n.Path.Length != 0).Select(n => Fq(n.Path));
        var values = tree.Nodes.SelectMany(n => ValueNames(n).Select(v => Fq($"{n.Path}|{v}")));
        var sb = new StringBuilder(
            FishHead(fn, tree.Name, string.Join(' ', paths), string.Join(' ', values))
        );
        foreach (var node in tree.Nodes)
        {
            var head = $"complete -c {tree.Name} -n {Fq($"{fn}_at \"{node.Path}\"")}";
            foreach (var child in node.Children)
            {
                sb.Append($"{head} -a {Fq(child.Word)}{FishHint(child.Hint)}\n");
            }
            foreach (var option in node.Options)
            {
                var names = string.Concat(option.Names.Select(FishName));
                var value = option.Type is null ? "" : " -r -F";
                var hint = FishHint(CommandTree.FirstLine(option.Description));
                sb.Append($"{head}{names}{value}{hint}\n");
            }
            if (node.Command is { Arguments.Count: > 0 })
            {
                sb.Append($"{head} -F\n");
            }
        }
        return sb.ToString();
    }

    /// <summary>A PowerShell script that registers a native argument completer.</summary>
    /// <param name="model">The model.</param>
    /// <returns>The script.</returns>
    public static string PowerShell(CommandModel model)
    {
        var tree = CommandTree.From(model);
        var sb = new StringBuilder();
        sb.Append($"# PowerShell completion for {tree.Name}\n# {Generated}\n\n");
        sb.Append(
            $"Register-ArgumentCompleter -Native -CommandName {Ps(tree.Name)} -ScriptBlock {{\n"
        );
        sb.Append("    param($wordToComplete, $commandAst, $cursorPosition)\n");
        void Table(string variable, Func<CommandTree.Node, IEnumerable<string>> words) =>
            CaseTable(
                sb,
                $"    ${variable} = @{{\n",
                tree,
                n =>
                    words(n).ToList() is { Count: > 0 } list
                        ? $"        {Ps(n.Path)} = @({string.Join(", ", list.Select(Ps))})"
                        : null,
                "    }\n"
            );
        Table("children", n => n.Children.Select(c => c.Word));
        Table("options", n => n.Options.SelectMany(o => o.Names));
        sb.Append("    $values = @(\n");
        foreach (var node in tree.Nodes)
        {
            foreach (var name in ValueNames(node))
            {
                sb.Append($"        {Ps($"{node.Path}|{name}")}\n");
            }
        }
        sb.Append("    )\n    $hints = @{\n");
        foreach (var node in tree.Nodes)
        {
            foreach (var (key, text) in Hints(node))
            {
                sb.Append($"        {Ps($"{node.Path}|{key}")} = {Ps(text)}\n");
            }
        }
        sb.Append("    }\n").Append(PowerShellMain);
        return sb.ToString();
    }

    /// <summary>A clink (cmd.exe) Lua script built on <c>clink.argmatcher</c>.</summary>
    /// <param name="model">The model.</param>
    /// <returns>The script.</returns>
    public static string Clink(CommandModel model)
    {
        var tree = CommandTree.From(model);
        var ids = tree.Nodes.Select((n, i) => (n, i)).ToDictionary(p => p.n, p => $"node_{p.i}");
        var sb = new StringBuilder();
        sb.Append($"-- clink completion for {tree.Name}\n-- {Generated}\n\n");
        sb.Append("local value = clink.argmatcher():addarg(clink.filematches)\n");
        // Children before parents: a parent links the matchers of its next words.
        foreach (var node in tree.Nodes.Reverse())
        {
            var id = ids[node];
            sb.Append(
                node.Path.Length == 0
                    ? $"\n-- {tree.Name}\nlocal {id} = clink.argmatcher({Lua(tree.Name)})\n"
                    : $"\n-- {tree.Name} {node.Path}\nlocal {id} = clink.argmatcher()\n"
            );
            if (node.Children.Count != 0)
            {
                var words = node.Children.Select(c => $"{Lua(c.Word)} .. {ids[c]}");
                sb.Append($"{id}:addarg({{ {string.Join(", ", words)} }})\n");
            }
            var flags = node
                .Options.SelectMany(o =>
                    o.Names.Select(n => o.Type is null ? Lua(n) : $"{Lua(n)} .. value")
                )
                .ToList();
            if (flags.Count != 0)
            {
                sb.Append($"{id}:addflags({{ {string.Join(", ", flags)} }})\n");
            }
            var hints = Hints(node).ToList();
            if (hints.Count != 0)
            {
                sb.Append($"{id}:adddescriptions({{\n");
                foreach (var (key, text) in hints)
                {
                    sb.Append($"    [{Lua(key)}] = {Lua(text)},\n");
                }
                sb.Append("})\n");
            }
            if (node.Command is not { Arguments.Count: > 0 })
            {
                sb.Append($"{id}:nofiles()\n");
            }
        }
        return sb.ToString();
    }

    /// <summary>Walks the typed words to the command path, then completes its options or next words.</summary>
    private static string BashMain(string fn, string name) =>
        Template(
            $$"""

            {{fn}}() {
                local cur=${COMP_WORDS[COMP_CWORD]} cmd='' word i skip=0
                for ((i = 1; i < COMP_CWORD; i++)); do
                    word=${COMP_WORDS[i]}
                    if ((skip)); then
                        skip=0
                    elif [[ $word == -* ]]; then
                        [[ " $({{fn}}_values "$cmd") " == *" $word "* ]] && skip=1
                    elif [[ " $({{fn}}_children "$cmd") " == *" $word "* ]]; then
                        cmd=${cmd:+$cmd }$word
                    fi
                done
                if ((skip)); then
                    COMPREPLY=()
                elif [[ $cur == -* ]]; then
                    COMPREPLY=($(compgen -W "$({{fn}}_options "$cmd")" -- "$cur"))
                else
                    COMPREPLY=($(compgen -W "$({{fn}}_children "$cmd")" -- "$cur"))
                fi
            }

            complete -o default -F {{fn}} {{name}}

            """
        );

    /// <summary>The zsh walk; it runs at once when autoloaded from <c>$fpath</c>, or registers when sourced.</summary>
    private static string ZshMain(string fn, string name) =>
        Template(
            $$"""

            {{fn}}() {
              local cmd='' word i skip=0
              local -a items names
              for ((i = 2; i < CURRENT; i++)); do
                word=${words[i]}
                items=()
                if ((skip)); then
                  skip=0
                elif [[ $word == -* ]]; then
                  {{fn}}_values "$cmd"
                  ((${items[(Ie)$word]})) && skip=1
                else
                  {{fn}}_children "$cmd"
                  names=(${items%%:*})
                  ((${names[(Ie)$word]})) && cmd=${cmd:+$cmd }$word
                fi
              done
              items=()
              if ((skip)); then
                _files
              elif [[ $PREFIX == -* ]]; then
                {{fn}}_options "$cmd"
                _describe -t options option items
              else
                {{fn}}_children "$cmd"
                if ((${#items})); then
                  _describe -t commands command items
                else
                  _files
                fi
              fi
            }

            if [[ ${zsh_eval_context[-1]} == loadautofunc ]]; then
              {{fn}} "$@"
            else
              compdef {{fn}} {{name}}
            fi

            """
        );

    /// <summary>The fish helpers: the path the typed words select, and a test for it.</summary>
    private static string FishHead(string fn, string name, string paths, string values) =>
        Template(
            $$"""
            # fish completion for {{name}}
            # {{Generated}}

            set -g {{fn}}_paths {{paths}}
            set -g {{fn}}_values {{values}}

            function {{fn}}_path
                set -l tokens (commandline -opc)
                set -e tokens[1]
                set -l cmd ''
                set -l skip 0
                for word in $tokens
                    set -l next (string trim -- "$cmd $word")
                    if test $skip = 1
                        set skip 0
                    else if string match -q -- '-*' $word
                        contains -- "$cmd|$word" ${{fn}}_values; and set skip 1
                    else if contains -- $next ${{fn}}_paths
                        set cmd $next
                    end
                end
                echo $cmd
            end

            function {{fn}}_at
                set -l at ({{fn}}_path)
                test "$at" = "$argv[1]"
            end

            complete -c {{name}} -f

            """
        );

    /// <summary>The PowerShell walk over the command's elements up to the cursor.</summary>
    private static readonly string PowerShellMain = Template(
        """
            $cmd = ''
            $skip = $false
            foreach ($element in ($commandAst.CommandElements | Select-Object -Skip 1)) {
                if ($element.Extent.EndOffset -ge $cursorPosition) { break }
                $word = $element.ToString()
                if ($skip) {
                    $skip = $false
                } elseif ($word.StartsWith('-')) {
                    $skip = $values -contains "$cmd|$word"
                } elseif ($children[$cmd] -contains $word) {
                    $cmd = "$cmd $word".Trim()
                }
            }
            if ($skip) { return }
            $list = if ($wordToComplete.StartsWith('-')) { $options[$cmd] } else { $children[$cmd] }
            foreach ($item in $list) {
                if ($item.StartsWith($wordToComplete, [System.StringComparison]::Ordinal)) {
                    $hint = $hints["$cmd|$item"]
                    if (-not $hint) { $hint = $item }
                    [System.Management.Automation.CompletionResult]::new($item, $item, 'ParameterValue', $hint)
                }
            }
        }

        """
    );

    /// <summary>One table keyed by path: the open text, a row per node that has one, the close text.</summary>
    private static void CaseTable(
        StringBuilder sb,
        string open,
        CommandTree tree,
        Func<CommandTree.Node, string?> row,
        string close
    )
    {
        sb.Append(open);
        foreach (var line in tree.Nodes.Select(row).OfType<string>())
        {
            sb.Append(line).Append('\n');
        }
        sb.Append(close);
    }

    /// <summary>A node's next words and option names with the first line of their description.</summary>
    private static IEnumerable<(string Key, string Text)> Hints(CommandTree.Node node) =>
        node
            .Children.Select(c => (Key: c.Word, Text: c.Hint))
            .Concat(
                node.Options.SelectMany(o =>
                    o.Names.Select(n => (Key: n, Text: CommandTree.FirstLine(o.Description)))
                )
            )
            .Where(h => h.Text.Length != 0);

    private static IEnumerable<string> ValueNames(CommandTree.Node node) =>
        node.Options.Where(o => o.Type is not null).SelectMany(o => o.Names);

    /// <summary>A raw-string script body with <c>\n</c> line ends whatever the source file uses.</summary>
    private static string Template(string text) => text.ReplaceLineEndings("\n");

    /// <summary><c>name:hint</c> for zsh's <c>_describe</c>; a colon in the name is escaped.</summary>
    private static string Described(string name, string hint)
    {
        var escaped = name.Replace(":", "\\:", StringComparison.Ordinal);
        return hint.Length == 0 ? escaped : $"{escaped}:{hint}";
    }

    /// <summary><c>-l name</c> for <c>--name</c>, <c>-s n</c> for <c>-n</c>, <c>-o name</c> for <c>-name</c>.</summary>
    private static string FishName(string name) =>
        name.StartsWith("--", StringComparison.Ordinal) ? $" -l {Fq(name[2..])}"
        : name.Length == 2 ? $" -s {Fq(name[1..])}"
        : $" -o {Fq(name[1..])}";

    private static string FishHint(string hint) => hint.Length == 0 ? "" : $" -d {Fq(hint)}";

    /// <summary>A POSIX shell single-quoted word.</summary>
    private static string Sh(string text) =>
        $"'{text.Replace("'", "'\\''", StringComparison.Ordinal)}'";

    /// <summary>A fish single-quoted word.</summary>
    private static string Fq(string text) =>
        $"'{text.Replace("\\", "\\\\", StringComparison.Ordinal).Replace("'", "\\'", StringComparison.Ordinal)}'";

    /// <summary>A PowerShell single-quoted string.</summary>
    private static string Ps(string text) =>
        $"'{text.Replace("'", "''", StringComparison.Ordinal)}'";

    /// <summary>A Lua double-quoted string.</summary>
    private static string Lua(string text) =>
        $"\"{text.Replace("\\", "\\\\", StringComparison.Ordinal).Replace("\"", "\\\"", StringComparison.Ordinal)}\"";

    /// <summary>A shell function name from a program name: anything but ASCII letters and digits becomes <c>_</c>.</summary>
    private static string Identifier(string name) =>
        string.Concat(name.Select(c => char.IsAsciiLetterOrDigit(c) ? c : '_'));
}
